Import.EveryEventSaysWhose.source:
Effect.fn("Import.EveryEventSaysWhose")(function* ({ events }) {
        const actor = yield* CurrentActor
        return A.every(events, (e) => (isActCounted(e) ? e.actor === actor.memberId : e.by === actor.memberId))
      })

Import.OnlyItsOwnOrganizationChangesAnIm.source:
Effect.fn("Import.OnlyItsOwnOrganizationChangesAnImport")(function* ({
        before
      }) {
        if (isUnstaged(before)) return true
        const actor = yield* CurrentActor
        return actor.organizationId === before.organizationId
      })

